$id = (int)($_GET['id'] ?? 0); $statement = $pdo->prepare('SELECT * FROM services WHERE id = ?'); $statement->execute([$id]); $service = $statement->fetch(); if (!$service) { http_response_code(404); exit('Service not found.'); }
if ($_SERVER['REQUEST_METHOD'] === 'POST') { verify_csrf(); $name = post_string('name'); $type = post_string('type') === 'date' ? 'date' : 'service'; $slug = slugify(post_string('slug') ?: $name); $short_description = post_string('short_description'); $description = post_string('description'); $status = post_string('status') === 'inactive' ? 'inactive' : 'active'; $is_featured = isset($_POST['is_featured']) ? 1 : 0; if ($name === '' || strlen($name) > 150 || $slug === '' || strlen($slug) > 180 || $short_description === '' || strlen($short_description) > 255 || $description === '') { flash('error', 'Enter valid name, slug, short description, and description values.'); } elseif (service_slug_exists($pdo, $slug, $id)) { flash('error', 'That slug is already in use. Choose another one.'); } else { $uploaded_image = upload_service_image($_FILES['image'] ?? null); if (uploaded_file_was_submitted($_FILES['image'] ?? null) && $uploaded_image === null) { flash('error', 'Upload a JPG, PNG, or WebP image up to 2 MB.'); } else { $image = $uploaded_image ?: $service['image']; try { $update = $pdo->prepare('UPDATE services SET name = ?, type = ?, slug = ?, short_description = ?, description = ?, image = ?, status = ?, is_featured = ? WHERE id = ?'); $update->execute([$name, $type, $slug, $short_description, $description, $image, $status, $is_featured, $id]); if ($uploaded_image) delete_service_image($service['image']); flash('success', 'Service updated.'); redirect('index.php'); } catch (PDOException $exception) { delete_service_image($uploaded_image); flash('error', 'The service could not be saved. Check that the slug is unique.'); } } } }
